create or replace function finance_private.current_accounting_feedback_caller_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
revoke all on function finance_private.current_accounting_feedback_caller_is_trusted() from public,anon,authenticated;
create or replace function finance_api.record_accounting_export_feedback(p_provider_id text,p_external_event_id text,p_accounting_batch_id uuid,p_status text,p_content_hash text,p_external_batch_id text,p_package_results jsonb,p_correlation_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_batch finance.accounting_batches%rowtype;v_payload jsonb;v_payload_hash text;v_existing_hash text;v_package_count integer;v_result_count integer;v_previous_hash text;v_audit_hash text;v_before_hash text;v_after_hash text;v_new_version bigint;
begin
 if not finance_private.current_accounting_feedback_caller_is_trusted() then raise exception using errcode='42501',message='accounting feedback caller denied';end if;
 if coalesce(pg_catalog.btrim(p_provider_id),'')='' or pg_catalog.length(p_provider_id)>100 or coalesce(pg_catalog.btrim(p_external_event_id),'')='' or pg_catalog.length(p_external_event_id)>200 or p_accounting_batch_id is null or p_status not in ('ACCEPTED','PARTIALLY_ACCEPTED','REJECTED') or p_content_hash!~'^[a-fA-F0-9]{64}$' or (p_external_batch_id is not null and (pg_catalog.btrim(p_external_batch_id)='' or pg_catalog.length(p_external_batch_id)>200)) or p_correlation_id is null or (p_package_results is not null and pg_catalog.jsonb_typeof(p_package_results)<>'array') then raise exception using errcode='22023',message='required accounting feedback fields missing';end if;
 p_package_results:=coalesce(p_package_results,'[]'::jsonb);
 v_payload:=pg_catalog.jsonb_build_object('externalEventId',p_external_event_id,'accountingBatchId',p_accounting_batch_id,'status',p_status,'contentHash',p_content_hash,'externalBatchId',p_external_batch_id,'packageResults',p_package_results);
 v_payload_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_payload::text,'UTF8'),'sha256'),'hex');
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('accounting-feedback:'||p_provider_id||':'||p_external_event_id,0));
 select im.payload_hash into v_existing_hash from finance.inbox_messages im where im.source_system=p_provider_id and im.message_id=p_external_event_id;
 if found then if v_existing_hash=v_payload_hash then return pg_catalog.jsonb_build_object('outcome','DUPLICATE');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select * into v_batch from finance.accounting_batches b where b.id=p_accounting_batch_id for update;
 if not found then raise exception using errcode='P0002',message='accounting batch not found';end if;
 if v_batch.target_adapter_code<>p_provider_id or v_batch.content_hash<>p_content_hash then raise exception using errcode='23514',message='accounting feedback identity mismatch';end if;
 if v_batch.status not in ('EXPORT_QUEUED','EXPORTED') then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select count(*) into v_package_count from finance.accounting_batch_packages p where p.accounting_batch_id=v_batch.id;v_result_count:=pg_catalog.jsonb_array_length(p_package_results);
 if v_package_count<1 then raise exception using errcode='23514',message='accounting package required';end if;
 if exists(select 1 from pg_catalog.jsonb_array_elements(p_package_results) x where pg_catalog.jsonb_typeof(x)<>'object' or coalesce(x->>'packageId','')!~'^[0-9a-fA-F-]{36}$' or x->>'status' not in ('ACCEPTED','REJECTED') or (x->>'safeErrorCode' is not null and (pg_catalog.btrim(x->>'safeErrorCode')='' or pg_catalog.length(x->>'safeErrorCode')>100)) or (x->>'externalPackageId' is not null and pg_catalog.btrim(x->>'externalPackageId')='')) then raise exception using errcode='22023',message='invalid accounting package result';end if;
 if (select count(distinct x->>'packageId') from pg_catalog.jsonb_array_elements(p_package_results) x)<>v_result_count then raise exception using errcode='23514',message='duplicate accounting package result';end if;
 if exists(select 1 from pg_catalog.jsonb_array_elements(p_package_results) x left join finance.accounting_batch_packages p on p.accounting_batch_id=v_batch.id and p.id=(x->>'packageId')::uuid where p.id is null) then raise exception using errcode='23514',message='accounting package result is not batch member';end if;
 if p_status='PARTIALLY_ACCEPTED' and (v_result_count<>v_package_count or not exists(select 1 from pg_catalog.jsonb_array_elements(p_package_results) x where x->>'status'='ACCEPTED') or not exists(select 1 from pg_catalog.jsonb_array_elements(p_package_results) x where x->>'status'='REJECTED')) then raise exception using errcode='23514',message='partial accounting package result must be complete and mixed';end if;
 if p_status in ('ACCEPTED','REJECTED') and v_result_count>0 and (v_result_count<>v_package_count or exists(select 1 from pg_catalog.jsonb_array_elements(p_package_results) x where x->>'status'<>p_status)) then raise exception using errcode='23514',message='terminal accounting package result mismatch';end if;
 insert into finance.inbox_messages(legal_entity_id,source_system,message_id,payload_hash,schema_version,payload,status,result_reference,processed_at_utc,correlation_id) values(v_batch.legal_entity_id,p_provider_id,p_external_event_id,v_payload_hash,1,v_payload,'PROCESSED',v_batch.id::text,pg_catalog.now(),p_correlation_id);
 if v_result_count=0 then update finance.accounting_batch_packages set status=p_status,safe_error_code=null,correlation_id=p_correlation_id where accounting_batch_id=v_batch.id;else update finance.accounting_batch_packages p set status=x.status,external_package_id=coalesce(x.external_package_id,p.external_package_id),safe_error_code=x.safe_error_code,correlation_id=p_correlation_id from (select (r->>'packageId')::uuid package_id,r->>'status' status,r->>'externalPackageId' external_package_id,r->>'safeErrorCode' safe_error_code from pg_catalog.jsonb_array_elements(p_package_results) r) x where p.accounting_batch_id=v_batch.id and p.id=x.package_id;end if;
 update finance.accounting_batch_entries e set export_status=p.status,safe_error_code=p.safe_error_code,correlation_id=p_correlation_id from finance.accounting_batch_packages p where e.accounting_batch_package_id=p.id and p.accounting_batch_id=v_batch.id and e.status='ACTIVE';
 v_new_version:=v_batch.version+1;update finance.accounting_batches set status=p_status,external_batch_id=coalesce(p_external_batch_id,external_batch_id),version=v_new_version,correlation_id=p_correlation_id where id=v_batch.id and version=v_batch.version;
 if not found then raise exception using errcode='40001',message='accounting batch version conflict';end if;
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(v_batch.legal_entity_id,'finance.accounting','ACCOUNTING_EXPORT_STATUS_CHANGED','accounting_batch',v_batch.id,v_new_version,pg_catalog.jsonb_build_object('batchId',v_batch.id,'status',p_status,'externalEventId',p_external_event_id,'externalBatchId',p_external_batch_id,'contentHash',p_content_hash,'version',v_new_version),v_payload_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||v_batch.legal_entity_id::text,0));select ae.integrity_hash into v_previous_hash from finance.audit_events ae where ae.legal_entity_id=v_batch.legal_entity_id order by ae.created_at_utc desc,ae.id desc limit 1;v_before_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(v_batch.status||':'||v_batch.version::text,'UTF8'),'sha256'),'hex');v_after_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_status||':'||v_new_version::text,'UTF8'),'sha256'),'hex');v_audit_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous_hash,'GENESIS')||':'||v_batch.id::text||':ACCOUNTING_EXPORT_FEEDBACK:'||v_before_hash||':'||v_after_hash||':'||p_external_event_id||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');
 insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(v_batch.legal_entity_id,null,'EXTERNAL_PROVIDER','ACCOUNTING_EXPORT_FEEDBACK','accounting_batch',v_batch.id,'ALLOW',v_before_hash,v_after_hash,v_previous_hash,v_audit_hash,pg_catalog.jsonb_build_object('provider',p_provider_id,'externalEventId',p_external_event_id,'status',p_status,'packageResultCount',v_result_count),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','COMMITTED','batchId',v_batch.id,'status',p_status,'version',v_new_version);
end $$;
revoke all on function finance_api.record_accounting_export_feedback(text,text,uuid,text,text,text,jsonb,uuid) from public,anon,authenticated;
